contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerAddr, address newOwner) public {
        vm.assume(ownerAddr != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(ownerAddr != newOwner);
        vm.prank(ownerAddr);
        c.transferOwnership(ownerAddr);

        bool isOwner = (msg.sender == ownerAddr);
        address ownerBefore = c.owner();
        vm.prank(msg.sender);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        address ownerAfter = c.owner();

        if (isOwner) {
            assertTrue(ok && ownerAfter == newOwner);
        } else {
            assertTrue(ownerAfter == ownerAddr);
        }
    }
}

