pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        // The reference contract satisfies: only the owner succeeds in calling owned().
        // We fuzz any possible caller address (actor).
        vm.assume(actor != address(0));

        // First, make actor the owner by pranking the current owner (initially address(0)? No, Solidity sets deployer as owner? Actually deployer is address(this) in setUp. We prank as address(this) which is the initial owner.).
        // Initial owner is the tester contract itself (address(this)).
        vm.prank(address(this));
        c.transferOwnership(actor);

        // Now actor is the owner. We'll check if actor can call owned().
        bool successOwner;
        vm.prank(actor);
        try c.owned() {
            successOwner = true;
        } catch {
            successOwner = false;
        }

        // Also check if a random non-owner caller (we use address(1) after ensuring it's not the owner) can call owned().
        address nonOwner = address(1);
        if (nonOwner == actor) {
            nonOwner = address(2);
        }
        bool successNonOwner;
        vm.prank(nonOwner);
        try c.owned() {
            successNonOwner = true;
        } catch {
            successNonOwner = false;
        }

        // General rule: In the correct implementation, the owner gets true, the non-owner gets false.
        // The buggy version allows both to succeed, breaking the property.
        assertTrue(successOwner && !successNonOwner);
    }
}

